#!/usr/bin/env python3
"""Ligne A : met CLAUDE.md à jour pour la nouvelle coquille (remplacements ciblés).
Usage : python3 etape_claude.py CLAUDE.md"""
import sys
p = sys.argv[1]
s = open(p, encoding='utf-8').read()

def rep(a, b):
    global s
    assert s.count(a) == 1, (a[:80], s.count(a))
    s = s.replace(a, b)

rep("boutons `.mob-mat-btn` du tiroir (HTML)", "intercalaires `.mob-mat-btn.mat-tab` de la navigation (HTML)")
rep("`buildChapData` + `const MATS` (tiroir), `const MAT_TAGS` (tiroir **et** Aujourd'hui)",
    "`buildChapData` + `const MATS` + `MAT_NOMS` (navigation), `const MAT_TAGS` (Aujourd'hui)")
rep("CSS `.flash-mat-*`, `.mt-*`, `.mob-mat-btn.active[data-mat]`, ", "CSS `.flash-mat-*`, jetons `[data-mat=\"X\"]` (région JETONS), ")
rep("La seule navigation visible est le **tiroir `#mob-drawer`**, sur mobile (☰) comme sur desktop (« Chapitres » `#nav-toggle-btn`).",
    "La seule navigation visible est **`#mob-drawer`** : **barre latérale permanente** à partir de 1200 px (repliée / affichée par `#nav-toggle-btn`, clé `navCollapsed`), **tiroir** de 768 à 1199 px (`#nav-toggle-btn`), **page plein écran « Chapitres »** au téléphone (☰ `#mob-menu-btn`). Les deux `<main>`, `#chap-pager` et le pied sont enveloppés dans **`<article id=\"app-main\" role=\"none\">`** (colonne de lecture, décalée par la barre latérale) : jamais un `<div>` ni un `<section>` englobant, que les `</div>` / `</section>` orphelins du contenu refermeraient (les chapitres sortiraient du `<main>`).")
rep("Au chargement (restauration à +120 ms), un `#hash` a priorité sur `lastPos` (`window.__navFromHash`). `popstate` rejoue la navigation.",
    "Au chargement (restauration à +120 ms), un `#hash` a priorité sur `lastPos` (`window.__navFromHash`). `popstate` rejoue la navigation. **Sommaire de la matière** : `#sommaire/<matière>` (`window.__ouvrirSommaire(mat)`, `__fermerSommaire()`, `__sommaireOuvert()` ; 2ᵉ clic sur l'intercalaire actif ; fermé par tout clic `.chap-btn`). **Retour Android** : au téléphone, une page plein écran ouverte (page Chapitres, feuille ⋯, Aujourd'hui, recherche, quiz, Bilan, fenêtres : liste `PAGES` de `urlRouting`) empile une entrée d'historique fictive (même URL) que « précédent » referme ; fermée autrement, l'entrée est retirée (`history.back`, popstate ignoré) ; un chapitre choisi depuis la page la **remplace** (`window.__consommerPageFictive()` avant le clic `.chap-btn`).")
rep("`lastPos` (dernier chapitre/panneau vu)",
    "`lastPos` (dernier chapitre/panneau vu `{chap, panel, t, s}` : `t` = horodatage, `s` = section courante « §3 Régime libre », facultatifs)")
rep("`readScale` (taille du texte A−/A+, index 0-2 → `--read-scale`).",
    "`readScale` (taille du texte A / A+ / A++, index 0-2 → `--read-scale` 1 / 1,1 / 1,2), `navCollapsed` (`'1'` = barre latérale des chapitres repliée sur ordinateur ; appliquée dès le script du `<head>`, classe `nav-replie` sur `<html>`).")
rep("**Tiroir « nouvelle génération »** : `#mob-filter` (filtre instantané TOUTES matières, accents ignorés, Entrée = 1ᵉʳ résultat, année ignorée volontairement) ; sections ★ Épinglés / ⌚ Récents en tête (hors filtre) ; sous-domaines repliables (`.mob-sub-toggle`) ; rangée `.mob-chap-row` = bouton chapitre + bouton épingle (frères, pas imbriqués). Module : `buildDrawerList`/`makeChapRow`/`CHAP_ITEM_BY_ID`.",
    "**Navigation des chapitres** (`grep -n 'NAVIGATION DES CHAPITRES'`, SPEC §4.3) : année (`#mob-year-bar`, segmenté) ; `#mob-filter` (filtre instantané TOUTES matières et les deux années, accents ignorés, Entrée = 1ᵉʳ résultat ; résultats groupés par matière, nom complet avec `<mark>`, sous-libellé « partie · année ») ; Épinglés (puces) et Récents (lignes, « Cours · §3 » pour le plus récent d'après `lastPos`), une seule rangée de puces au téléphone, jamais filtrés ni limités à l'année ; intercalaires `.mob-mat-btn.mat-tab` avec effectif de l'année (un 2ᵉ clic sur l'actif ouvre le Sommaire de la matière) ; parties repliables (`.nav-part-h.mob-sub-toggle`, clé `drawerCollapsed`) ; en 2ᵉ année, chaque partie finit par « + N chapitres de 1ʳᵉ année » (ouvrir l'un d'eux garde la 2ᵉ année) ; rangée `.mob-chap-row` (`data-mat`, `.cur` + `aria-current` pour le chapitre affiché) = bouton `.mob-chap-item` (nom court, « 2A », compteur des cartes dues) + bouton épingle `.mob-pin` (frères, pas imbriqués). Construction **paresseuse** (seulement si la navigation est visible). Page Chapitres du téléphone : tuiles Aujourd'hui / Bilan en tête. Module : `buildDrawerList`/`makeChapRow`/`CHAP_ITEM_BY_ID` ; API `window.__togglePin(id)`, `__isPinned(id)`, `__majNav()`. Même module : barre du téléphone (`#mob-header.mbar` : « matière · partie · année » + titre complet ; s'efface au défilement, revient avec « chapitre · onglet » + section courante donnée par le scroll-spy via `window.__surSection`) et feuille ⋯ (`#mob-more-menu.bsheet`, qui monte du bas).")
rep("ouvert par « Aujourd'hui » (menu **Plus** `#today-btn`, menu ⋯ mobile `#mob-today-btn`)",
    "ouvert par le bouton « Aujourd'hui » de l'en-tête (`#today-btn`), la tuile de la page Chapitres ou la 1ʳᵉ ligne de la feuille ⋯ du téléphone (`#mob-today-btn`)")
rep("`applyTheme` inaccessible (cliquer `#theme-btn`, ou `window.__setTheme(…)` ;",
    "`applyTheme` inaccessible (passer par le sélecteur comme un utilisateur : `choisirTheme(page, 'dark' | 'light' | 'auto', mobile)` de `tests/lib/outils.js` — popover de `#theme-btn`, feuille ⋯ au téléphone —, ou `window.__setTheme(…)` ;")
rep("+ 4 `<marker>` `sk-arrow-*` des schémas, en tête de `<body>`,",
    "+ 4 `<marker>` `sk-arrow-*` des schémas, en tête de `<body>`, complété juste avant l'en-tête par un 2ᵉ sprite de 12 icônes de la coquille (x, chev-down, chev-right, star, star-fill, sun, moon, auto, sidebar, filter, clock, wave),")
rep("- **En-tête desktop** : `.header-nav` (« Chapitres ») + `.header-actions` (Rechercher, menu Réviser, Bilan, Thème, menu **Plus** `#more-menu` : Aujourd'hui, Sauvegarde, Raccourcis, Formulaire, Imprimer, Cartes signalées, taille du texte). **Mobile** : `#mob-header` (☰, recherche, Réviser, thème, menu ⋯ sans Imprimer ni Raccourcis).",
    "- **En-tête ordinateur** `header.hdr` (collant, 56 px, ≥ 768 px) : `#nav-toggle-btn`, marque (carré « § » + `h1.brand-name`, l'unique `h1`), champ de recherche visible (`#search-btn`, Ctrl K), `#today-btn` « Aujourd'hui », `#dash-btn` « Bilan » (icônes seules sous 1100 px), « Réviser » primaire `#study-btn` + compteur → `#study-menu` (Révisions du jour, Quiz, Calcul mental), `#theme-btn` → popover `#theme-pop`, menu **Plus** `#more-menu` (Formulaire, Imprimer, Sauvegarde, Raccourcis, Cartes signalées, et « Dans ce chapitre » de 1200 à 1359 px). **Téléphone** : barre `#mob-header.mbar` (☰, titre sur 2 lignes, recherche, Réviser = révisions du jour, ⋯) et feuille ⋯ `#mob-more-menu` (Aujourd'hui, Bilan, Quiz, Calcul mental, Formulaire, Épingler, Cartes signalées, Sauvegarde, puis Thème et Texte en bas ; ni Imprimer ni Raccourcis). Aucune barre fixe en bas.")
rep("met à jour libellé/titre des boutons, suit le système en mode Auto et redessine le chapitre visible quand le thème effectif change. `#theme-btn` (relayé par `#mob-theme-btn`) fait tourner Auto → l'inverse du thème affiché → l'autre → Auto.",
    "coche le choix courant (`[data-theme-set]`, `aria-checked`), suit le système en mode Auto (et la mention « actuellement : clair/sombre ») et redessine le chapitre visible quand le thème effectif change. **Sélecteur explicite** : `#theme-btn` ouvre le popover `#theme-pop` (3 cartes Clair / Sombre / Auto à mini-vues — leurs couleurs littérales sont la seule exception à la règle « aucune couleur codée en dur » — et la taille du texte) ; au téléphone, segmenté en bas de la feuille ⋯ ; tout bouton `[data-theme-set]` appelle `setTheme`.")
open(p, 'w', encoding='utf-8').write(s)
print('CLAUDE.md à jour')
